<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class StoreTransportRouteRequest extends FormRequest {public function authorize():bool{return $this->user()?->can('transporte.rutas.gestionar')??false;}public function rules():array{$company=$this->user()->company_id;$id=$this->route('transportRoute')?->id;return['code'=>['required','string','max:50',Rule::unique('transport_routes')->where(fn($q)=>$q->where('company_id',$company))->ignore($id)],'name'=>'required|string|max:255','description'=>'nullable|string|max:2000','route_type'=>['required',Rule::in(array_keys(config('transport.route_types')))],'origin'=>'required|string|max:255','destination'=>'required|string|max:255','estimated_start_time'=>'nullable|date_format:H:i','estimated_arrival_time'=>'nullable|date_format:H:i','vehicle_id'=>['nullable',Rule::exists('transport_vehicles','id')->where(fn($q)=>$q->where('company_id',$company))],'default_driver_id'=>['nullable',Rule::exists('transport_personnel','id')->where(fn($q)=>$q->where('company_id',$company)->where('is_driver',1))],'default_monitor_id'=>['nullable',Rule::exists('transport_personnel','id')->where(fn($q)=>$q->where('company_id',$company)->where('is_monitor',1))],'status'=>'required|in:active,inactive'];}}
